// Minimum inspectors needed to cover `n` items with coverage radius `d`.
// Each inspector covers at most (2*d + 1) consecutive items, so the answer is:
// ceil(n / (2*d + 1)).
fn min_inspectors(n: i8, d: i8) -> i8 {
    // Use a wider integer type for intermediate arithmetic to avoid overflow surprises.
    let n = n as i32;
    let d = d as i32;

    let block = 2 * d + 1;              // max items one inspector can cover
    let ans = (n + block - 1) / block;  // integer-ceil division

    ans as i8
}

